Method.Source:
/// <summary>
/// CoC - MPJ-21310 (Substitutes). Circumvent min/max quantity check for certain
/// substitute scenarios.
/// </summary>
/// <param name = "_orderSetup">_orderSetup</param>
/// <param name = "_errorCorrectionMethods">_errorCorrectionMethods</param>
/// <returns>Return value</returns>
protected InventMovementQuantityValidator createQuantityValidator(
    InventItemOrderSetupMap                         _orderSetup,
    InventMovementQuantityErrorCorrectionMethods    _errorCorrectionMethods)
{
    InventMovementQuantityValidator validator = next createQuantityValidator(_orderSetup, _errorCorrectionMethods);
    if(this.buffer() is SalesLine)
    {
        SalesLine salesLine = this.buffer();
        if(salesLine.METSkipMinMaxMultipleCheck)
        {
            validator.metOverrideErrorCorrectionMethods(InventMovementQuantityErrorCorrectionMethod::AcceptUserInput);
        }
    }
    return validator;
}
